const CACHE='striangle-v3';const FILES=['./','./index.html','./style.css','./app.mjs','./engine.mjs','./market-data.mjs','./optimizer.mjs','./optimizer-worker.mjs','./manifest.webmanifest','./icon.svg','./icon-192.png','./icon-512.png'];
self.addEventListener('install',e=>e.waitUntil(caches.open(CACHE).then(c=>c.addAll(FILES)).then(()=>self.skipWaiting())));
self.addEventListener('activate',e=>e.waitUntil(caches.keys().then(keys=>Promise.all(keys.filter(k=>k.startsWith('striangle-')&&k!==CACHE).map(k=>caches.delete(k)))).then(()=>self.clients.claim())));
self.addEventListener('fetch',e=>{if(e.request.method!=='GET'||new URL(e.request.url).origin!==self.location.origin)return;const url=new URL(e.request.url),allowed=FILES.map(p=>new URL(p,self.registration.scope).pathname);if(e.request.mode==='navigate'){e.respondWith(fetch(e.request).catch(()=>caches.match(new URL('./index.html',self.registration.scope))));return;}if(!allowed.includes(url.pathname))return;e.respondWith(caches.match(e.request).then(hit=>hit||fetch(e.request)));});
